nm -D --defined-only -S -n libmonosgen-2.0.so 2>/dev/null | awk '
{
  if (NF >= 4) {
    addr = strtonum("0x" $1)
    size = strtonum("0x" $2)
    name = $4
    print addr, size, name
  }
}' > /tmp/syms_sorted.txt

